import {config as c} from './config.js';
import {decisions} from './content/decisions.js';
import {facts} from './content/truth.js';
import {allyStories} from './content/ally.js';
import {promises,cardThemes,cardDesigns} from './content/promises.js';
import {getAIResponse,validMessage} from './ai.js';
import {storage,parseBackup} from './storage.js';
import {createRound} from './game.js';
import {drawCard,readyFonts,makeCard,saveFile} from './learning-card.js';
import {icon} from './icons.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const app=$('#app'),base=new URL('../',import.meta.url),asset=p=>new URL(p,base).href;
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const ar=n=>Number(n).toLocaleString('ar-SA');
const u=c.ui;
const games={simulation:{items:decisions,state:createRound(decisions)},truth:{items:facts,state:createRound(facts)},ally:{items:allyStories,state:createRound(allyStories)}};
let kiosk=false,lastActivity=Date.now(),generation=0,chatEpoch=0,unlocked=false,toastTimer,promiseRevision=0,pendingImport=null;
const path=location.pathname.replace(/\/(index\.html)?$/,'');
const page=path.endsWith('/admin')?'admin':path.endsWith('/wall')?'wall':'home';
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6500)}
const btn=(text,id,cls='primary',glyph='arrow')=>`<button type="button" id="${id}" class="button ${cls}">${text}${icon(glyph)}</button>`;
function brand(){return `<a class="brand" href="${base}" aria-label="الرئيسية"><span class="brand-symbol">${icon('leaf')}</span><span><strong>تقنية تنصت</strong><small>كلية الحاسبات وتقنية المعلومات · جامعة الطائف</small></span></a>`}
function header(){return `<a class="skip" href="#main">تجاوز إلى المحتوى</a><header class="site-header"><div class="container header-inner">${brand()}<div class="header-actions"><button class="icon-button" id="theme" aria-label="تبديل المظهر" aria-pressed="false">${icon('sun')}</button><a class="button compact help-link" href="${base}#support">المساعدة ${icon('heart')}</a>${page==='home'?'<button class="icon-button" id="menu" aria-label="قائمة الأقسام" aria-expanded="false">☰</button>':''}</div></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div><h2>${c.title}</h2><p>${c.organization}</p><p class="supervision">${c.supervision}</p></div><a class="qr-link" href="${c.publicUrl}" target="_blank" rel="noopener"><img src="${asset('assets/qr.svg')}" width="104" height="104" loading="lazy" alt="رمز فتح الموقع على الجوال"><span>خذ الأمل معك<small dir="ltr">hope-listens-taif.vercel.app</small></span></a></div><p class="privacy">${c.privacy}</p><div class="footer-bottom"><span>وعي أقرب. وخطوة أكثر أمانًا.</span><div><a href="${asset('wall/')}">شاشة الجدار</a><a href="${asset('admin/')}">إدارة هذا الجهاز</a></div></div></div></footer>`}
function sectionHead(index,title,description){const s=c.sections[index];return `<div class="section-heading"><div><span class="eyebrow">${ar(index+1).padStart(2,'٠')} / ${s.title}</span><h2 id="${s.id}-heading">${title}</h2><p>${description}</p></div><span class="section-emblem ${s.tone}">${icon(s.icon)}</span></div>`}
const heroArt=`<div class="hope-scene" aria-hidden="true"><div class="scene-grid"></div><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="hope-window"><svg viewBox="0 0 400 480" fill="none"><defs><linearGradient id="window-light" x1="200" y1="30" x2="200" y2="450" gradientUnits="userSpaceOnUse"><stop stop-color="#eff5d9"/><stop offset="1" stop-color="#b5d1b4"/></linearGradient><linearGradient id="leaf-light"><stop stop-color="#a5c699"/><stop offset="1" stop-color="#4a8068"/></linearGradient></defs><path d="M65 430V180a135 135 0 0 1 270 0v250" fill="url(#window-light)"/><path d="M205 427c-25-72 34-160-3-268" stroke="#456e55" stroke-width="6" stroke-linecap="round"/><path d="M206 286c-61 7-106-33-93-92 66 2 103 34 93 92Z" fill="url(#leaf-light)"/><path d="M209 237c64 6 103-30 99-92-62-1-104 35-99 92Z" fill="#5b8c71"/><path d="M202 180c-42-9-61-43-44-88 48 8 69 43 44 88Z" fill="#8bb482"/><path d="m202 278-67-60m79 11 70-57" stroke="#dfeada" stroke-width="2"/><ellipse cx="200" cy="430" rx="142" ry="17" fill="#294b3d" opacity=".09"/><path d="M47 446h306" stroke="#bdd1c0" stroke-width="2"/></svg></div><span class="scene-pill pill-one">${icon('shield')}مساحة آمنة للوعي</span><span class="scene-pill pill-two">${icon('spark')}قرار صغير، أثر يمتد</span><span class="scene-dot dot-one"></span><span class="scene-dot dot-two"></span><span class="scene-caption">كل بداية تحمل احتمالًا أجمل.</span></div>`;
function home(){app.innerHTML=`${header()}<nav class="journey-nav" id="journey-nav" aria-label="الأقسام السبعة"><div class="container">${c.sections.map((s,i)=>`<a href="#${s.id}"><span>${ar(i+1)}</span>${s.title}</a>`).join('')}</div></nav><main id="main"><div class="hero container"><div class="hero-copy"><span class="pill"><i></i>${c.hero.eyebrow}</span><h1>${c.hero.line1}<span>${c.hero.line2}</span></h1><p class="supervision">${c.supervision}</p><p class="hero-description">${c.hero.description}</p><p class="organization">${c.organization}</p><div class="hero-actions"><a class="button primary" href="#simulation">ابدأ رحلتك ${icon('arrow')}</a><a class="text-link" href="#experiences">اكتشف التجارب السبع <span>↙</span></a></div><div class="hero-signals"><span>${icon('shield')}بلا أحكام</span><span>${icon('lock')}خصوصيتك أولًا</span><span>${icon('heart')}الدعم متاح</span></div></div>${heroArt}</div><div class="container experiences" id="experiences"><div class="mini-heading"><span>سبع محطات. ومساحة لاختيار بدايتك.</span><span>استكشف على مهل <b>↓</b></span></div><div class="experience-grid">${c.sections.map((s,i)=>`<a href="#${s.id}" class="experience-card ${s.tone}"><div class="card-top">${icon(s.icon)}<span class="card-number">${ar(i+1)}</span></div><h2>${s.title}</h2><p>${s.desc}</p><div class="card-bottom"><span>${s.tag}</span>${icon('arrow')}</div></a>`).join('')}</div></div>
<section id="simulation" class="section tinted" aria-labelledby="simulation-heading"><div class="container">${sectionHead(0,'قرار اليوم، أثر الغد.','جرّب موقفًا من الحياة. خذ وقتك، وتعلّم مهارة تساعدك خارج الشاشة.')}<div class="decision-layout"><aside class="panel metrics" id="metrics"></aside><div class="panel game" id="simulation-game"></div></div></div></section>
<section id="companion" class="section" aria-labelledby="companion-heading"><div class="container">${sectionHead(1,'أحيانًا، البداية حديث.','اسأل عن الوقاية أو مساندة صديق أو الوصول إلى الدعم.')}<div class="companion-layout"><div class="companion-note"><span class="large-flower">${icon('spark')}</span><h3>سؤالك له مساحة هنا.</h3><p>${u.chatNote}</p><p class="fine">المحادثة مؤقتة ولا تُحفظ. لا تكتب اسمك أو أي معلومات شخصية.</p><a class="text-link" href="#support">أحتاج دعمًا مختصًا ${icon('arrow')}</a></div><div class="chat panel"><div class="chat-header"><span class="avatar">${icon('chat')}</span><div><strong>رفيق الأمل</strong><small>ردود توعوية جاهزة · يعمل محليًا</small></div><button class="icon-button" id="clear-chat" aria-label="مسح المحادثة">${icon('reset')}</button></div><div class="chat-log" id="chat-log" role="log" aria-live="polite" aria-label="المحادثة"></div><div class="suggestions">${c.suggestions.map(t=>`<button type="button" data-question="${esc(t)}">${t}</button>`).join('')}</div><form class="chat-form" id="chat-form"><label class="sr-only" for="chat-input">سؤالك</label><input id="chat-input" maxlength="500" autocomplete="off" required placeholder="ما الذي يدور في بالك؟"><button class="button primary" aria-label="إرسال السؤال">${icon('arrow')}</button></form></div></div></div></section>
<section id="truth" class="section cream-section" aria-labelledby="truth-heading"><div class="container">${sectionHead(2,'بين المعلومة… والحقيقة.','ليست كل معلومة شائعة صحيحة. اختر إجابتك، ثم اطّلع على التفسير والمصدر.')}<div class="panel game fact-game" id="truth-game"></div></div></section>
<section id="hope-wall" class="section" aria-labelledby="hope-wall-heading"><div class="container">${sectionHead(3,'كلمة منك، أمل لغيرك.','رسالة صغيرة قد تجعل شخصًا يشعر أنه ليس وحده.')}<div class="wall-grid" id="wall-grid" aria-live="polite"></div><div class="wall-compose panel"><form id="wall-form"><label for="wall-text">رسالتك دون اسم</label><textarea id="wall-text" maxlength="150" rows="3" required placeholder="اكتب كلمة تزرع الأمل…"></textarea><div class="field-meta"><span>بلا روابط أو أرقام أو معلومات شخصية.</span><output id="wall-count">٠ / ١٥٠</output></div><div class="wall-controls"><label>لون البطاقة<select id="wall-color"><option value="green">أخضر</option><option value="blue">أزرق</option><option value="yellow">كريمي</option><option value="pink">وردي</option></select></label><label>رمزها<select id="wall-icon"><option>♡</option><option>✦</option><option>❋</option><option>✧</option></select></label><button class="button primary">إرسال للمراجعة ${icon('arrow')}</button>${btn('تحميل بطاقة شخصية','wall-download','secondary','download')}</div></form><div class="local-note">${icon('lock')}<div><strong>هذا الجدار محلي على جهازك.</strong><p>${u.wallNote} تُعرض الرسالة هنا بعد موافقة مشرف هذا المتصفح فقط.</p><a href="${asset('wall/')}" target="_blank" rel="noopener">فتح شاشة العرض ↗</a></div></div></div></div></section>
<section id="ally" class="section blue-section" aria-labelledby="ally-heading"><div class="container">${sectionHead(4,'كن قريبًا. كن السند.','أحيانا تكون الكلمة الصحيحة بداية طريق النجاة.')}<div class="ally-layout"><div class="ally-art" aria-hidden="true"><div class="speech speech-one">أنا هنا لأسمعك.</div><div class="people-art">${icon('people')}</div><div class="speech speech-two">ما الخطوة التي نأخذها معًا؟</div></div><div class="panel game" id="ally-game"></div></div></div></section>
<section id="promise" class="section" aria-labelledby="promise-heading"><div class="container">${sectionHead(5,'وعد صغير. وبداية صادقة.','كل بداية جميلة تبدأ بوعد صادق لنفسك.')}<div class="promise-layout"><form id="promise-form" class="promise-controls"><fieldset><legend>اختر وعدًا يعبّر عنك</legend><div class="promise-options">${promises.map((p,i)=>`<button type="button" data-promise="${i}" aria-pressed="${i===0}" class="promise-option ${i===0?'selected':''}">${p}</button>`).join('')}</div></fieldset><label for="promise-text">أو اكتب وعدك الخاص</label><textarea id="promise-text" maxlength="150" rows="3">${promises[0]}</textarea><p class="fine">لا يُحفظ نص الوعد ولا يُرفع إلى أي خادم.</p><div class="select-grid"><label>التصميم<select id="promise-design">${Object.entries(cardDesigns).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>اللون<select id="promise-theme">${Object.entries(cardThemes).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label></div><label class="check-label"><input type="checkbox" id="promise-dated">إضافة تاريخ اليوم</label><div class="actions">${btn('تحميل بطاقتي','promise-download','primary','download')}${btn('مشاركة البطاقة','promise-share','secondary','arrow')}</div><p class="fine" id="share-hint">المشاركة متاحة حسب جهازك؛ يمكنك دائمًا تحميل البطاقة.</p></form><div class="preview-wrap"><span class="preview-caption">وعدك… كما سيظهر في البطاقة</span><canvas id="promise-canvas" width="1080" height="1350" role="img" aria-label="معاينة بطاقة وعد لنفسي"></canvas><span class="preview-foot">يصنع محليًا. ويبقى لك.</span></div></div></div></section>
<section id="support" class="section support-section" aria-labelledby="support-heading"><div class="container">${sectionHead(6,'طلب المساعدة قوة، وليس ضعفًا.','خطوة واحدة نحو شخص مختص قد تفتح لك طريقًا مختلفًا.')}<div class="support-layout"><div><h3>ابدأ بما تستطيع قوله.</h3><p class="support-quote">«أنا أمرّ بوقت صعب، وأحتاج أن أتحدث مع مختص».</p><ol class="support-steps"><li>اختر شخصًا موثوقًا واطلب مرافقته إن أحببت.</li><li>استمع لصديقك دون حكم، واعرض المساعدة دون تشخيص.</li><li>عند خطر مباشر، اطلب الطوارئ المحلية أو توجّه إلى أقرب قسم طوارئ. لا تواجه الموقف وحدك.</li></ol></div><div>${c.support.map(s=>`<article class="support-card"><div><h3>${s.title}</h3><p>${s.desc}</p><a href="${s.url}" target="_blank" rel="noopener">المصدر الرسمي ↗</a></div><a class="phone" href="tel:${s.number}" aria-label="الاتصال بـ ${s.title} على ${s.number}">${s.number}</a></article>`).join('')}<p class="fine">مراجعة المصادر: ${c.reviewed}. التجارب توعوية، ولا تحل محل التقييم أو العلاج المتخصص.</p></div></div></div></section></main>${footer()}<div class="booth-toolbar"><button id="restart-journey" title="مسح جلسة الزائر فقط">${icon('reset')}رحلة جديدة</button><button id="kiosk" aria-pressed="false">${icon('expand')}وضع الكشك</button><a href="#support">${icon('heart')}المساعدة</a></div>`;
 bindCommon();Object.keys(games).forEach(renderGame);resetChat();renderNotes();storage.subscribe(renderNotes);
 $('#menu').onclick=()=>{const open=$('#journey-nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};
 $$('#journey-nav a').forEach(a=>a.onclick=()=>{$('#journey-nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});
 $('#chat-form').onsubmit=e=>{e.preventDefault();sendChat($('#chat-input').value)};$('#clear-chat').onclick=resetChat;$$('[data-question]').forEach(b=>b.onclick=()=>sendChat(b.dataset.question));
 $('#wall-text').oninput=()=>$('#wall-count').textContent=`${ar([...$('#wall-text').value].length)} / ١٥٠`;
 $('#wall-form').onsubmit=async e=>{e.preventDefault();const input=$('#wall-text'),text=input.value.trim();if(!validMessage(text))return notify(u.filterError);const submit=$('button',e.currentTarget);submit.disabled=true;try{await storage.submit({text,color:$('#wall-color').value,icon:$('#wall-icon').value});input.value='';$('#wall-count').textContent='٠ / ١٥٠';notify(u.pending)}catch(error){notify(error.message||u.storageError)}finally{submit.disabled=false}};
 $('#wall-download').onclick=()=>download('wall-download',{kind:'wall',text:$('#wall-text').value.trim(),theme:$('#wall-color').value==='yellow'?'sand':$('#wall-color').value==='blue'?'blue':'green'},'رسالة-أمل.png');
 $('#promise-form').onsubmit=e=>e.preventDefault();$$('[data-promise]').forEach(b=>b.onclick=()=>{$('#promise-text').value=promises[Number(b.dataset.promise)];updatePromiseSelection();previewPromise()});
 $('#promise-text').oninput=()=>{updatePromiseSelection();previewPromise()};['promise-theme','promise-design','promise-dated'].forEach(id=>$('#'+id).onchange=previewPromise);
 $('#promise-download').onclick=()=>download('promise-download',promiseOptions(),'وعد-لنفسي.png');$('#promise-share').onclick=sharePromise;
 $('#restart-journey').onclick=()=>confirmAction('بدء رحلة جديدة؟','سيتم مسح القرارات والمحادثة ومسودات البطاقات فقط. تبقى رسائل الجدار محفوظة.',()=>resetJourney());$('#kiosk').onclick=toggleKiosk;
 previewPromise();observeSections();
}
function progressMarkup(id,round,total){return `<div class="game-top"><span>${round.done?'اكتملت التجربة':`${id==='truth'?'السؤال':'الموقف'} ${ar(round.index+1)} من ${ar(total)}`}</span><button class="text-button" data-reset="${id}" aria-label="إعادة تجربة ${c.sections.find(s=>s.id===id)?.title}">إعادة البداية ${icon('reset')}</button></div><progress class="game-progress" aria-label="تقدم التجربة" max="${total}" value="${round.index+(round.chosen!==null?1:0)}"></progress>`}
function renderGame(id){const {items,state:r}=games[id],el=$('#'+id+'-game');if(!el)return;
 if(id==='simulation')$('#metrics').innerHTML=`<span class="eyebrow">أثر اختياراتك</span><h3>كل خطوة تُحدث فرقًا.</h3>${c.metrics.map((label,i)=>`<div class="metric"><div><label for="metric-${i}">${label}</label><b>${ar(r.scores[i])}</b></div><progress id="metric-${i}" max="100" value="${r.scores[i]}"></progress></div>`).join('')}<p class="fine">${u.simulationNote}</p>`;
 if(r.done){el.innerHTML=`${progressMarkup(id,r,items.length)}<div class="completion"><span class="completion-icon">${icon(id==='truth'?'spark':'leaf')}</span><h3 tabindex="-1">${id==='truth'?'المعرفة تفتح بابًا للوعي.':id==='ally'?'أن تكون سندًا… مهارة تتعلّمها.':'كل خطوة واعية تستحق التقدير.'}</h3>${id==='truth'?`<p class="score"><strong>${ar(r.correct)}</strong> / ${ar(items.length)}</p><p>إجابات صحيحة. راجع التفسيرات وجرّب مرة أخرى متى أحببت.</p><details><summary>مراجعة الحقائق والمصادر</summary>${items.map(f=>`<div class="review-fact"><strong>${f.claim} — ${f.truth?'حقيقة':'خرافة'}</strong><p>${f.explanation}</p><a href="${f.source.url}" target="_blank" rel="noopener">${f.source.title} ↗</a></div>`).join('')}</details>`:`<p>ما تعلمته يبقى معك خارج هذه الشاشة.</p><ul class="learning-list">${items.map(s=>`<li>${icon('check')}${s.skill}</li>`).join('')}</ul>`}<div class="actions">${id==='simulation'?btn('تحميل بطاقة ما تعلمته','learning-download','primary','download'):''}<button class="button ${id==='simulation'?'secondary':'primary'}" data-reset="${id}">جرّب من جديد ${icon('reset')}</button><a class="text-link" href="#${id==='simulation'?'companion':id==='truth'?'hope-wall':'promise'}">المحطة التالية ${icon('arrow')}</a></div></div>`;
 }else{const item=items[r.index],answered=r.chosen!==null,good=answered&&(id==='truth'?r.chosen===item.truth:r.chosen===item.best);
 el.innerHTML=`${progressMarkup(id,r,items.length)}<div class="question-body"><span class="pill">${id==='truth'?'حقيقة أم خرافة؟':item.tag}</span><h3 tabindex="-1">${id==='truth'?item.claim:item.title}</h3>${item.story?`<p class="story">${item.story}</p>`:''}<div class="choices ${id==='truth'?'binary':''}">${(id==='truth'?['حقيقة','خرافة']:item.choices).map((text,i)=>`<button type="button" class="choice ${answered&&r.chosen===(id==='truth'?i===0:i)?'selected':''}" data-choice="${i}" ${answered?'disabled':''}><span class="choice-marker">${id==='truth'?(i===0?'✓':'×'):ar(i+1)}</span><span>${text}</span></button>`).join('')}</div></div>${answered?`<div class="feedback ${good?'positive':'reflect'}" role="status"><strong>${icon(good?'check':'spark')}${id==='truth'?(good?'إجابة صحيحة.':'فرصة لتصحيح المعلومة.'):good?'خطوة أكثر أمانًا.':'لنتأمل هذا الاختيار.'}</strong>${id==='simulation'?`<div class="timeline">${item.outcomes[r.chosen].map((text,i)=>`<div><small>${[u.days,u.months,u.years][i]}</small><p>${text}</p></div>`).join('')}</div>`:`<p>${id==='truth'?item.explanation:item.outcomes[r.chosen]}</p>`}${id==='truth'?`<a class="source" href="${item.source.url}" target="_blank" rel="noopener">${item.source.title} ↗</a>`:`<p class="skill"><b>${u.best}:</b> ${item.choices[item.best]}<br>${item.skill}</p>`}<button class="button primary" data-next="${id}">${r.index===items.length-1?'شاهد ما تعلمته':'التالي'} ${icon('arrow')}</button></div>`:''}`;
 $$('[data-choice]',el).forEach(b=>b.onclick=()=>{if(r.choose(id==='truth'?Number(b.dataset.choice)===0:Number(b.dataset.choice))){renderGame(id);$('[data-next]',el)?.focus({preventScroll:true})}});
 $('[data-next]',el)?.addEventListener('click',()=>{r.next();renderGame(id);$('h3',el)?.focus({preventScroll:true})});}
 $$('[data-reset]',el).forEach(b=>b.onclick=()=>{r.reset();renderGame(id);$('h3',el)?.focus({preventScroll:true})});
 if(id==='simulation'&&$('#learning-download'))$('#learning-download').onclick=()=>download('learning-download',{kind:'learning',skills:decisions.map(s=>s.skill),design:'orbit'},'ما-تعلمته.png');
}
function bubble(text,user=false){const el=document.createElement('div');el.className='bubble '+(user?'user':'assistant');el.textContent=text;$('#chat-log').append(el);while($('#chat-log').children.length>50)$('#chat-log').firstElementChild.remove();$('#chat-log').scrollTop=$('#chat-log').scrollHeight}
function resetChat(){chatEpoch++;$('#chat-log').replaceChildren();bubble(c.replies.hello);$('#chat-input').value=''}
async function sendChat(value){const text=value.trim().slice(0,500);if(!text)return;const epoch=chatEpoch;bubble(text,true);$('#chat-input').value='';try{const reply=await getAIResponse(text);if(epoch===chatEpoch)bubble(reply)}catch{if(epoch===chatEpoch)bubble(c.replies.fallback)}}
function noteHTML(row,seed=false){return `<article class="hope-note ${row.color}"><span class="note-symbol" aria-hidden="true">${esc(row.icon)}</span><p>${esc(row.text)}</p><small>${seed?'رسالة افتتاحية من فريق المشروع':'رسالة زائر معتمدة على هذا الجهاز'}</small></article>`}
async function renderNotes(){const el=$('#wall-grid');if(!el)return;try{const rows=(await storage.list()).filter(r=>r.status==='approved');el.innerHTML=c.seeds.map(r=>noteHTML(r,true)).join('')+rows.slice(-80).map(r=>noteHTML(r)).join('')}catch(error){el.innerHTML=c.seeds.map(r=>noteHTML(r,true)).join('');notify(error.message)}}
function promiseOptions(){return {text:$('#promise-text').value.trim(),theme:$('#promise-theme').value,design:$('#promise-design').value,date:$('#promise-dated').checked?new Intl.DateTimeFormat('ar-SA',{dateStyle:'long',calendar:'gregory',timeZone:'Asia/Riyadh'}).format(new Date()):''}}
function updatePromiseSelection(){$$('[data-promise]').forEach(b=>{const selected=$('#promise-text').value===promises[Number(b.dataset.promise)];b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)})}
async function previewPromise(){const revision=++promiseRevision;await readyFonts();if(revision!==promiseRevision)return;const options=promiseOptions();drawCard($('#promise-canvas').getContext('2d'),options);$('#promise-canvas').setAttribute('aria-label','بطاقة وعد لنفسي: '+options.text)}
async function download(id,options,name){const b=$('#'+id),epoch=generation;if(options.kind!=='learning'&&!validMessage(options.text))return notify(u.filterError);b.disabled=true;try{const {blob}=await makeCard(options);if(epoch===generation){saveFile(blob,name);notify('بطاقتك جاهزة للتحميل على جهازك.')}}catch{notify('تعذّر إنشاء البطاقة. حاول مرة أخرى.')}finally{b.disabled=false}}
async function sharePromise(){const options=promiseOptions();if(!validMessage(options.text))return notify(u.filterError);const b=$('#promise-share'),epoch=generation;b.disabled=true;try{const {blob}=await makeCard(options);if(epoch!==generation)return;const file=new File([blob],'hope-promise.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:c.title})}else{saveFile(blob,'وعد-لنفسي.png');notify('المشاركة المباشرة غير متاحة؛ حُمّلت البطاقة لتشاركها من جهازك.')}}catch(error){if(error.name!=='AbortError')notify('تعذّرت المشاركة؛ استخدم زر تحميل البطاقة.')}finally{b.disabled=false}}
function bindCommon(){$('#theme').onclick=()=>{const on=document.documentElement.classList.toggle('dark');$('#theme').setAttribute('aria-pressed',on)}}
function confirmAction(title,description,action,typed=false){const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-description').textContent=description;$('#confirm-word').hidden=!typed;$('#confirm-input').value='';$('#confirm-ok').disabled=typed;$('#confirm-input').oninput=()=>$('#confirm-ok').disabled=typed&&$('#confirm-input').value!=='حذف';$('#confirm-ok').onclick=async()=>{dialog.close();try{await action()}catch(error){notify(error.message)}};$('#confirm-cancel').onclick=()=>dialog.close();dialog.showModal()}
function resetJourney(){generation++;Object.values(games).forEach(g=>g.state.reset());Object.keys(games).forEach(renderGame);resetChat();$('#wall-form').reset();$('#wall-count').textContent='٠ / ١٥٠';$('#promise-form').reset();$('#promise-text').value=promises[0];updatePromiseSelection();previewPromise();$('#confirm-dialog').close();lastActivity=Date.now();history.replaceState(null,'',location.pathname);window.scrollTo({top:0,behavior:'instant'});notify('بدأت رحلة جديدة. بقيت رسائل الجدار محفوظة.');}
async function toggleKiosk(){kiosk=!kiosk;lastActivity=Date.now();document.body.classList.toggle('kiosk',kiosk);$('#kiosk').setAttribute('aria-pressed',kiosk);$('#kiosk').innerHTML=icon('expand')+(kiosk?'إنهاء الكشك · ٦٠ ثانية':'وضع الكشك');if(kiosk)await fullScreen();else if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{})}
async function fullScreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else if(page==='wall')await document.exitFullscreen()}catch{notify('ملء الشاشة غير متاح هنا. يمكنك استخدام زر المتصفح أو إعدادات شاشة البوث.')}}
function observeSections(){if(!('IntersectionObserver'in window))return;const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('.journey-nav a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-15% 0px -60% 0px'});$$('main > section').forEach(s=>observer.observe(s))}
function wallPage(){app.innerHTML=`${header()}<main id="main" class="wall-display container"><div class="display-heading"><span class="pill">رسائل أمل من هذا الجهاز</span><h1>كلمة منك، أمل لغيرك.</h1><p>تظهر رسائل الزوار المعتمدة فقط، إلى جانب الرسائل الافتتاحية المميزة بوضوح.</p><div class="actions">${btn('ملء الشاشة','fullscreen','primary','expand')}<a class="button secondary" href="${base}#hope-wall">أضف رسالة</a></div></div><div class="wall-grid" id="wall-grid" aria-live="polite"></div><p class="fine">لا توجد مزامنة بين الأجهزة. افتح الإدارة وشاشة العرض في المتصفح نفسه وعلى رابط الموقع نفسه.</p></main>${footer()}`;bindCommon();renderNotes();storage.subscribe(renderNotes);$('#fullscreen').onclick=fullScreen}
function adminPage(){app.innerHTML=`${header()}<main id="main" class="admin container"><div class="section-heading"><div><span class="eyebrow">وضع المشرف المحلي</span><h1>مساحة للعناية بالكلمات.</h1><p>${u.adminNote}</p></div><span class="section-emblem mint">${icon('lock')}</span></div><div id="admin-content"></div></main>${footer()}`;bindCommon();renderAdmin();storage.subscribe(()=>{if(unlocked)renderAdminList()})}
function renderAdmin(){const el=$('#admin-content');if(!unlocked){el.innerHTML=`<form class="panel admin-gate" id="admin-gate"><h2>أنت تدير رسائل هذا المتصفح فقط.</h2><p>لا كلمة مرور ثابتة ولا حسابات. الوصول هنا حاجز استخدام لمنع التعديل غير المقصود، ويمكن لمن يستخدم الجهاز فتحه.</p><label class="check-label"><input type="checkbox" required id="admin-ack">أفهم أنني أدير البيانات المحلية على هذا الجهاز.</label><button class="button primary">فتح وضع المشرف ${icon('arrow')}</button></form>`;$('#admin-gate').onsubmit=e=>{e.preventDefault();unlocked=true;lastActivity=Date.now();renderAdmin()};return}
 el.innerHTML=`<div class="admin-tools panel"><div class="actions">${btn('قفل الإدارة','admin-lock','secondary','lock')}${btn('تصدير المعتمد JSON','admin-export','secondary','download')}<label class="button secondary import-label">استيراد نسخة<input id="admin-import" type="file" accept="application/json,.json"></label>${btn('إعادة ضبط بيانات الجدار','admin-reset','danger','reset')}</div><p class="fine">الاستيراد يدمج النسخة المعتمدة بعد تأكيدك؛ لا يكرر المعرّفات ولا يرسل شيئًا لأي جهاز. يقفل وضع المشرف بعد ٦٠ ثانية من الخمول.</p></div><div class="admin-counts" id="admin-counts"></div><div class="queue" id="queue"></div>`;
 $('#admin-lock').onclick=()=>{unlocked=false;pendingImport=null;renderAdmin()};$('#admin-export').onclick=async()=>{try{saveFile(new Blob([await storage.export()],{type:'application/json'}),'hope-wall-backup.json');notify('تم تصدير الرسائل المعتمدة فقط.')}catch(e){notify(e.message)}};
 $('#admin-import').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>1000000)throw Error('حجم الملف أكبر من 1 ميغابايت');const text=await f.text();const rows=parseBackup(text);pendingImport=text;confirmAction('استيراد نسخة محلية؟',`تحتوي النسخة ${ar(rows.length)} رسالة معتمدة. تأكد أنك تعرف مصدرها؛ ستظهر الرسائل المستوردة على جدار هذا الجهاز.`,async()=>{if(!unlocked||!pendingImport)return;const n=await storage.import(pendingImport);pendingImport=null;notify(`أُضيفت ${ar(n)} رسالة؛ المعرّفات المكررة لم تتغير.`);renderAdminList()})}catch(error){notify(error.message)}};
 $('#admin-reset').onclick=()=>confirmAction('حذف بيانات الجدار من هذا المتصفح؟','سيتم حذف الرسائل المحلية بكل حالاتها، دون التأثير على أجهزة أخرى. صدّر نسخة احتياطية أولًا. اكتب «حذف» للتأكيد.',async()=>{if(!unlocked)return;await storage.reset();notify('حُذفت رسائل هذا المتصفح.');renderAdminList()},true);renderAdminList();
}
async function renderAdminList(){if(!unlocked||!$('#queue'))return;try{const rows=await storage.list();if(!unlocked)return;const labels={pending:'بانتظار المراجعة',approved:'معتمدة',rejected:'مرفوضة'};$('#admin-counts').innerHTML=`<div><strong>${ar(rows.length)}</strong>إجمالي الرسائل المحلية</div>`+Object.entries(labels).map(([key,label])=>`<div><strong>${ar(rows.filter(r=>r.status===key).length)}</strong>${label}</div>`).join('');$('#queue').innerHTML=rows.length?rows.slice().reverse().map(r=>`<article class="panel queue-item"><span class="status ${r.status}">${labels[r.status]}</span><p>${esc(r.text)}</p><div class="actions">${r.status!=='approved'?`<button class="button primary" data-id="${r.id}" data-action="approved">موافقة</button>`:''}${r.status!=='rejected'?`<button class="button secondary" data-id="${r.id}" data-action="rejected">رفض</button>`:''}<button class="button danger" data-id="${r.id}" data-action="delete">حذف</button></div></article>`).join(''):'<div class="panel empty-state">لا توجد رسائل محلية بعد. الرسائل الافتتاحية ضمن محتوى الموقع وليست رسائل زوار.</div>';
 $$('[data-action]').forEach(b=>b.onclick=()=>{const act=async()=>{if(!unlocked)return;await storage.moderate(b.dataset.id,b.dataset.action);renderAdminList()};if(b.dataset.action==='delete')confirmAction('حذف هذه الرسالة؟','سيُحذف سجلها المحلي نهائيًا من هذا المتصفح.',act);else act().catch(e=>notify(e.message))})
 }catch(e){$('#queue').textContent=e.message;notify(e.message)}}
// مؤقت واحد لكل صفحة. لا حذف دائم عند نهاية جلسة الزائر.
['pointerdown','pointermove','keydown','input','touchstart','scroll'].forEach(name=>window.addEventListener(name,()=>lastActivity=Date.now(),{passive:true}));
setInterval(()=>{if(Date.now()-lastActivity<c.kioskSeconds*1000)return;if(page==='admin'&&unlocked){unlocked=false;pendingImport=null;$('#confirm-dialog').close();renderAdmin();notify('أُقفل وضع المشرف بعد الخمول.')}if(page==='home'&&kiosk)resetJourney()},1000);
if(page==='home')home();else if(page==='wall')wallPage();else adminPage();
